"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[7541],{1341(t){t.exports=JSON.parse('{"tag":{"label":"Simple Algorithms","permalink":"/concepts/tags/simple-algorithms","allTagsPath":"/concepts/tags","count":3,"items":[{"id":"fundamental-problem-domains/bubble-sort","title":"Bubble Sort","description":"Bubble sort is probably the best-known sorting algorithm, and also one of the least efficient. It is worth studying precisely because it is so simple: it lets us practise the exact analysis of comparisons and moves, introduces the important idea of inversions, and shows how small changes (a stop condition, a change of direction) affect the behaviour without changing the complexity.","permalink":"/concepts/fundamental-problem-domains/bubble-sort"},{"id":"fundamental-problem-domains/insertion-sort","title":"Insertion Sort","description":"Insertion sort is the method most people use, without thinking, to sort a hand of cards it performs fewer comparisons and moves, and it is extremely fast on data that is already almost sorted. For this reason, it is used inside many professional sorting algorithms.","permalink":"/concepts/fundamental-problem-domains/insertion-sort"},{"id":"fundamental-problem-domains/selection-sort","title":"Selection Sort","description":"Selection sort follows the most direct strategy imaginable: find the smallest element and put it first; then find the smallest of the rest and put it second; and so on. It is the simple algorithm with the most predictable behaviour, the one that performs the fewest exchanges, and, unlike the previous two, it is not stable.","permalink":"/concepts/fundamental-problem-domains/selection-sort"}],"unlisted":false}}')}}]);